        // library treats SPD/SPSD inputs elsewhere, e.g. CHO/CHOP).
        static void ValidateLQRDims(in doubleMxN A, in doubleMxN B, in doubleMxN Q, in doubleMxN R,
                                    string ctx, out int n, out int m)
        {
