            var SB = new doubleMxN(n, m, Allocator.Temp);
            Blas.dot(in S, in B, ref SB);                          // SB = S*B

            var Rbar = new doubleMxN(m, m, Allocator.Temp);
            Blas.dotSym(in B, in SB, ref Rbar);                    // Rbar = Bᵀ(SB), symmetric since S is
            for (int i = 0; i < m; i++)
