            var BSA = new doubleMxN(m, n, Allocator.Temp);
            Blas.dot(in SB, in A, ref BSA, transposeA: true);      // BSA = (SB)ᵀA = BᵀSA

            var L = new doubleMxN(m, m, Allocator.Temp);
            var P = new Pivot(m, Allocator.Temp);
            RankInfo rinfo = CHOP.decomp(in Rbar, ref L, ref P);

            if (rinfo.Solved)
            {
                for (int i = 0; i < m; i++)
                    for (int j = 0; j < n; j++)
                        K[i, j] = BSA[i, j];
                CHOP.decompSolve(ref L, in P, rinfo.rank, ref K);  // K := Rbar⁻¹ BSA

                var SA = new doubleMxN(n, n, Allocator.Temp);
                Blas.dot(in S, in A, ref SA);                      // SA = S*A
                var AtSA = new doubleMxN(n, n, Allocator.Temp);
                Blas.dotSym(in A, in SA, ref AtSA);                // AtSA = Aᵀ(SA), symmetric since S is
                var BSATK = new doubleMxN(n, n, Allocator.Temp);
                Blas.dotSym(in BSA, in K, ref BSATK);              // BSAᵀK = BSAᵀ R̄⁻¹ BSA, symmetric since R̄ is

                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++)
                        Snext[i, j] = Q[i, j] + AtSA[i, j] - BSATK[i, j];

                SA.Dispose(); AtSA.Dispose(); BSATK.Dispose();
