        /// <summary>
        /// Finite-horizon discrete LQR: backward Riccati recursion from the terminal cost
        /// <paramref name="Qf"/> over <paramref name="N"/> steps, using the SAME shared Riccati-step
        /// kernel as the infinite-horizon paths. <paramref name="Kschedule"/> is (N*m) x n; the gain
        /// for step k lives in rows [k*m, (k+1)*m). For large N with <c>Qf == Q</c>, row block 0
        /// approaches the infinite-horizon K.
        /// </summary>
        /// <param name="N">Horizon length, &gt;= 1.</param>
        /// <param name="Kschedule">Output, (N*m) x n (overwritten row-block by row-block).</param>
        public static RiccatiInfo lqrSchedule(in doubleMxN A, in doubleMxN B, in doubleMxN Q, in doubleMxN R,
                                          in doubleMxN Qf, int N, ref doubleMxN Kschedule)
        {
            ValidateLQRDims(in A, in B, in Q, in R, "LQR.lqrSchedule", out int n, out int m);
            if (!Qf.IsSquare || Qf.M_Rows != n)
                throw new ArgumentException("LQR.lqrSchedule: Qf must be n x n");
            if (N < 1)
                throw new ArgumentException("LQR.lqrSchedule: N must be >= 1");
            if (Kschedule.M_Rows != N * m || Kschedule.N_Cols != n)
                throw new ArgumentException("LQR.lqrSchedule: Kschedule must be (N*m) x n");

            var Sk = new doubleMxN(in Qf, Allocator.Temp);
            var Snext = new doubleMxN(n, n, Allocator.Temp);
            var Kstep = new doubleMxN(m, n, Allocator.Temp);

            double blowup = Riccati.BlowupThreshold(in Q, in Qf);
            bool rankDeficient = false;
            RiccatiStatus status = RiccatiStatus.Converged;
            int steps = 0;
            double residual = double.PositiveInfinity;

            for (int k = N - 1; k >= 0; k--)
            {
                var rinfo = RiccatiStep(in A, in B, in Q, in R, in Sk, ref Snext, ref Kstep);
                steps++;
                if (!rinfo.Solved) { status = RiccatiStatus.Diverged; residual = double.PositiveInfinity; break; }
                if (rinfo.status == DirectSolveStatus.RankDeficient) rankDeficient = true;

                Riccati.SymmetrizeInPlace(ref Snext);
                double newNorm = Riccati.FrobeniusNorm(in Snext);
                if (!(newNorm <= blowup)) { status = RiccatiStatus.Diverged; residual = double.PositiveInfinity; break; }

                for (int r = 0; r < m; r++)
                    for (int c = 0; c < n; c++)
                        Kschedule[k * m + r, c] = Kstep[r, c];

                residual = Riccati.FrobeniusNormDiff(in Snext, in Sk) / math.max(1.0, newNorm);

                Sk.CopyFrom(in Snext);
            }

            Sk.Dispose(); Snext.Dispose(); Kstep.Dispose();

            return new RiccatiInfo { iterations = steps, residual = residual, status = status, rankDeficient = rankDeficient };
        }

        /// <summary>
        /// Linear-Quadratic-Gaussian convenience: solves the control DARE (via <see cref="lqr"/>)
        /// and the filter DARE (via <see cref="Kalman.steadyStateGain"/>) for the SAME dynamics A --
        /// both are the same SDA (structure-preserving doubling) engine, the filter side reached
        /// through the LQR/KF duality mapping (see Kalman.double.cs's file header). The separation
        /// principle means Klqr and Kkf can be designed independently and combined (estimate with
        /// Kkf, then feed the estimate to u=-Klqr·x̂) -- this call does not couple them beyond solving
        /// both from the same A.
        /// </summary>
        /// <param name="A">Dynamics, n x n (shared by both DAREs).</param>
        /// <param name="B">Control input, n x p.</param>
        /// <param name="H">Measurement matrix, m x n.</param>
        /// <param name="Qlqr">LQR state cost, n x n.</param>
        /// <param name="Rlqr">LQR control cost, p x p.</param>
        /// <param name="Qkf">Filter process noise covariance, n x n.</param>
        /// <param name="Rkf">Filter measurement noise covariance, m x m.</param>
        /// <param name="Klqr">Output LQR feedback gain, p x n.</param>
        /// <param name="Kkf">Output steady-state Kalman gain, n x m.</param>
        /// <param name="maxIter">SDA doubling-step budget for BOTH solves; &lt;=0 picks the
        /// library default.</param>
        public static LQGInfo lqg(in doubleMxN A, in doubleMxN B, in doubleMxN H,
                                  in doubleMxN Qlqr, in doubleMxN Rlqr,
                                  in doubleMxN Qkf, in doubleMxN Rkf,
                                  ref doubleMxN Klqr, ref doubleMxN Kkf, int maxIter = 0)
        {
            var lqrInfo = lqr(in A, in B, in Qlqr, in Rlqr, ref Klqr, maxIter);
            var kfInfo = Kalman.steadyStateGain(in A, in H, in Qkf, in Rkf, ref Kkf, maxIter);
            return new LQGInfo { lqrInfo = lqrInfo, kfInfo = kfInfo };
        }
    }

    /// <summary>
